path = ROOT + '/World/step9/effect_vocabulary.yaml'
txt = open(path, encoding='utf-8').read()
have = yaml.safe_load(txt)['effects']
clash = [n for n, *_ in NEW if n in have]
if clash: FAIL.append(('NAME CLASH WITH A STANDING EFFECT', clash))
dup = [n for n in set(x[0] for x in NEW) if sum(1 for x in NEW if x[0] == n) > 1]
if dup: FAIL.append(('DUPLICATE IN NEW', dup))
for name, op, en, he, ink, corpus, exam in NEW:
    if op not in ('status', 'block', 'heaven', 'debit', 'timer', 'transfer', 'body', 'destroy'): FAIL.append(('BAD OP', name, op))
    if ';' in he: FAIL.append(('SEMICOLON IN GLOSS', name))
    if not re.match(r'^[a-z_]+$', name): FAIL.append(('BAD NAME', name))
    if 'none located' in en or 'none located' in ink: FAIL.append(('UNLOCATED CITATION LEFT IN', name))
for k in REUSE:
    if k not in have: FAIL.append(('REUSE OF AN UNKNOWN EFFECT', k))
print('NEW %d; claims %d; failures %d' % (len(NEW), len(CLAIMS), len(FAIL)))
for f in FAIL: print('  ', f)
if FAIL or DRY:
    sys.exit(1 if FAIL else 0)
def q(s): return '"' + s.replace('\\', '\\\\').replace('"', '\\"') + '"'
out, n = [], 0
for name, op, en, he, ink, corpus, exam in NEW:
    if name in have: continue
    out.append("  %s:\n    en: %s\n    he: %s\n    ledger_op: %s\n    ink: %s\n    corpus: %s\n    exam: %s\n" % (name, q(en), q(he), op, q(ink), q(corpus), q(exam)))
    n += 1
if out:
    if not txt.endswith('\n'): txt += '\n'
    txt += "  # ---- O8 S4 FROM THE FORD TO THE COFFIN (2026-09-08; NARRATIVE_GAPS.md section 8c): the stretch's states in the tradition's own words, each ink claim verified by script ----\n" + ''.join(out)
m = 0
for name, add in REUSE.items():
    pat = re.compile(r'(^  %s:\n(?:(?!^  \S).*\n)*?^    ink: ")([^"\n]*)(")' % re.escape(name), re.M)
    mm = pat.search(txt)
    assert mm, ('no ink line for', name)
    if 'O8 S4' in mm.group(2): continue
    txt = txt[:mm.start(2)] + mm.group(2) + add.replace('"', '\\"') + txt[mm.end(2):]
    m += 1
open(path, 'w', encoding='utf-8').write(txt)
after = yaml.safe_load(open(path, encoding='utf-8'))['effects']
print('effects appended: %d (registry %d -> %d); reused ink lines extended: %d' % (n, len(have), len(after), m))
